"""Meeting notes file management.

Creates, finds, and opens per-meeting markdown files with YAML frontmatter
in the pa_workspace's notes/ directory.
"""

from __future__ import annotations

import logging
import re
import subprocess
import unicodedata
from collections.abc import Callable
from datetime import datetime
from pathlib import Path

import yaml

from personal_assistant_dashboard.config import WORK_DIR
from personal_assistant_dashboard.models import CalendarEvent
from personal_assistant_dashboard.utils import atomic_write_text

logger = logging.getLogger(__name__)

_FRONTMATTER_RE = re.compile(r"^---\n(.*?)\n---", re.DOTALL)


def notes_dir(workspace: Path = WORK_DIR) -> Path:
    """Return the path to the notes directory in the pa_workspace."""
    return workspace / "notes"


def _slugify(text: str, max_len: int = 50) -> str:
    """Convert text to a filename-safe slug."""
    text = unicodedata.normalize("NFKD", text)
    text = text.encode("ascii", "ignore").decode("ascii")
    text = re.sub(r"[^a-z0-9]+", "-", text.lower())
    text = text.strip("-")[:max_len].rstrip("-")
    return text or "untitled"


def _notes_filename(event: CalendarEvent) -> str:
    """Generate the filename for a meeting notes file."""
    start = event.get("start", "")
    summary = event.get("summary", "untitled")

    try:
        dt = datetime.fromisoformat(start)
        prefix = dt.strftime("%Y-%m-%d-%H%M")
    except (ValueError, TypeError):
        prefix = "unknown"

    slug = _slugify(summary)
    return f"{prefix}-{slug}.md"


def _build_frontmatter(event: CalendarEvent) -> dict[str, object]:
    """Build the YAML frontmatter dict from a calendar event."""
    attendee_emails = [a["email"] for a in event.get("attendees", []) if "email" in a]

    fm: dict[str, object] = {
        "meeting_id": event.get("id", ""),
        "title": event.get("summary", ""),
        "start_time": event.get("start", ""),
        "end_time": event.get("end", ""),
        "attendees": attendee_emails,
        "keywords": [],
    }

    if event.get("recurring_event_id"):
        fm["series"] = event.get("summary", "")

    return fm


def find_notes_file(
    event_id: str,
    workspace: Path = WORK_DIR,
) -> Path | None:
    """Find an existing notes file for a calendar event by meeting_id.

    Scans notes/ for files with matching meeting_id in YAML frontmatter.
    """
    ndir = notes_dir(workspace)
    if not ndir.is_dir():
        return None

    for md_file in sorted(ndir.glob("*.md")):
        try:
            content = md_file.read_text(encoding="utf-8")[:1024]
        except OSError:
            continue

        match = _FRONTMATTER_RE.match(content)
        if not match:
            continue

        try:
            data = yaml.safe_load(match.group(1))
        except yaml.YAMLError:
            continue

        if isinstance(data, dict) and data.get("meeting_id") == event_id:
            return md_file

    return None


def create_notes_file(
    event: CalendarEvent,
    workspace: Path = WORK_DIR,
) -> Path:
    """Create a new meeting notes markdown file with YAML frontmatter.

    Returns the path to the created file.
    """
    ndir = notes_dir(workspace)
    ndir.mkdir(parents=True, exist_ok=True)

    filename = _notes_filename(event)
    filepath = ndir / filename

    fm = _build_frontmatter(event)
    frontmatter_str = yaml.dump(fm, default_flow_style=False, sort_keys=False)
    content = f"---\n{frontmatter_str}---\n"

    atomic_write_text(filepath, content)
    logger.info("Created meeting notes: %s", filepath)
    return filepath


def open_notes_file(filepath: Path) -> None:
    """Open a notes file in the system default editor via xdg-open."""
    subprocess.Popen(["xdg-open", str(filepath)])


def invoke_prep_skill(
    filepath: Path,
    send_message: Callable[[str], None],
    workspace: Path = WORK_DIR,
) -> None:
    """Invoke the meeting-prep skill via the Chat tab's SDK agent.

    Sends ``/meeting-prep <relative-path>`` through the provided
    send_message callback (typically ChatTab.send_message).
    """
    try:
        rel_path = filepath.relative_to(workspace)
    except ValueError:
        rel_path = filepath

    logger.info("Invoking meeting-prep skill: %s", rel_path)
    send_message(f"/meeting-prep {rel_path.as_posix()}")
